sections.css:
.bcn-search-trigger {
  align-items: center;
  gap: var(--spacing-200);
  width: 100%;
  max-width: 520px;
  padding: var(--spacing-150) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  cursor: text;
  margin: 0 auto;
  transition:
    border-color 0.15s,
    background 0.15s;
  display: flex;
}
.bcn-search-trigger:hover {
  border-color: var(--color-border-brand);
  background: var(--color-background-elevation-raised);
}
.bcn-search-trigger:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: 2px;
}
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-search-trigger__placeholder {
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  font-size: var(--font-size-200);
  color: var(--color-content-default-tertiary);
  flex: 1;
  overflow: hidden;
}
.bcn-search-trigger__kbd {
  flex: none;
  gap: 2px;
  display: inline-flex;
}
.bcn-search-trigger__kbd kbd {
  min-width: 18px;
  height: 18px;
  font-family: inherit;
  font-size: 11px;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  background: var(--color-background-elevation-sunken);
  border: 1px solid var(--color-border-default);
  border-radius: 4px;
  justify-content: center;
  align-items: center;
  padding: 0 4px;
  display: inline-flex;
}
@media (width<=720px) {
  .bcn-search-trigger__placeholder {
    display: none;
  }
}
@media (width<=720px) {
  .bcn-search-trigger {
    max-width: max-content;
  }
}
.bcn-admin-btn .esa-icon {
  block-size: 14px;
  inline-size: 14px;
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-disclosure .esa-icon {
  transition: transform 0.15s;
}
.bcn-disclosure[aria-expanded="false"] .esa-icon {
  transform: rotate(-90deg);
}
@media (prefers-reduced-motion: reduce) {
  .bcn-disclosure .esa-icon {
    transition: none;
  }
}
.bcn-ev-staging__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-targets__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-background-utility-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__title,
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.breadcrumbs__items .esa-icon {
  color: var(--bcn-gray-400);
}
.page-layout__title h1 .esa-icon {
  color: var(--page-title-icon-color, var(--bcn-gray-1000));
  flex-shrink: 0;
}

.bcn-omni__panel {
  z-index: 1;
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-400, 12px);
  flex-direction: column;
  width: 860px;
  max-width: 100%;
  height: min(680px, 84vh);
  animation: 0.14s ease-out bcn-omni-enter;
  display: flex;
  position: relative;
  overflow: hidden;
  box-shadow: 0 24px 64px #141e2852;
}
.bcn-omni__searchrow {
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-300) var(--spacing-500);
  border-bottom: 1px solid var(--color-border-default);
  flex: none;
  display: flex;
}
.bcn-omni__searchicon {
  color: var(--color-content-default-tertiary);
  flex: none;
  display: inline-flex;
}
.bcn-omni__searchicon svg {
  width: 22px;
  height: 22px;
}
.bcn-omni__inputwrap {
  flex: 1;
  align-items: center;
  min-width: 0;
  display: flex;
  position: relative;
}
.bcn-omni__input {
  z-index: 1;
  width: 100%;
  min-width: 0;
  font-family: inherit;
  font-size: var(--font-size-400, 1.25rem);
  color: var(--color-content-default);
  background: 0 0;
  border: 0;
  outline: 0;
  margin: 0;
  padding: 0;
  line-height: 1.4;
  position: relative;
}
.bcn-omni__input::placeholder {
  color: var(--color-content-default-tertiary);
}
.bcn-omni__ghost {
  z-index: 0;
  font-family: inherit;
  font-size: var(--font-size-400, 1.25rem);
  color: var(--color-content-default-tertiary);
  white-space: pre;
  pointer-events: none;
  align-items: center;
  line-height: 1.4;
  display: flex;
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.bcn-omni__ghost-pad {
  color: #0000;
  white-space: pre;
}
.bcn-omni__clear {
  border-radius: var(--radius-full);
  background: var(--color-background-elevation-sunken);
  width: 26px;
  height: 26px;
  color: var(--color-content-default-secondary);
  cursor: pointer;
  border: 0;
  flex: none;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-omni__clear[hidden] {
  display: none;
}
.bcn-omni__clear:hover {
  background: var(--color-border-default);
}
.bcn-omni__split {
  flex: auto;
  min-height: 0;
  display: flex;
}
.bcn-omni__rail {
  box-sizing: border-box;
  width: 208px;
  padding: var(--spacing-200);
  border-right: 1px solid var(--color-border-default);
  scrollbar-width: none;
  flex-direction: column;
  flex: none;
  gap: 1px;
  display: flex;
  overflow-y: auto;
}
.bcn-omni__rail::-webkit-scrollbar {
  display: none;
}
.bcn-omni__body {
  min-width: 0;
  padding: var(--spacing-200) 0;
  flex: auto;
  overflow-y: auto;
}
.bcn-omni__body.is-landing {
  padding: var(--spacing-400);
  justify-content: center;
  align-items: center;
  display: flex;
}
.bcn-omni__showall {
  justify-content: center;
  align-items: center;
  gap: var(--spacing-200);
  width: 100%;
  padding: var(--spacing-300);
  background: var(--color-background-brand);
  color: var(--color-content-default-knockout);
  font-family: inherit;
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-semibold);
  cursor: pointer;
  border: 0;
  flex: none;
  display: flex;
}
.bcn-omni__showall[hidden] {
  display: none;
}
.bcn-omni__showall:hover {
  background: var(--color-background-brand-hover, var(--color-background-brand));
  filter: brightness(0.96);
}
.bcn-omni__footer {
  gap: var(--spacing-400);
  padding: var(--spacing-250) var(--spacing-500);
  border-top: 1px solid var(--color-border-default);
  font-size: var(--font-size-150);
  color: var(--color-content-default-tertiary);
  flex-wrap: wrap;
  flex: none;
  display: flex;
}
.bcn-omni__footer span {
  align-items: center;
  gap: 6px;
  display: inline-flex;
}
.bcn-omni-rail__item {
  align-items: center;
  gap: var(--spacing-200);
  width: 100%;
  padding: var(--spacing-150) var(--spacing-250);
  border-radius: var(--radius-200);
  color: var(--color-content-default-secondary);
  font-family: inherit;
  font-size: var(--font-size-150);
  text-align: left;
  cursor: pointer;
  background: 0 0;
  border: 0;
  transition:
    background 0.1s,
    color 0.1s;
  display: flex;
}
.bcn-omni-rail__item:not(:disabled):hover {
  background: var(--color-background-elevation-sunken);
  color: var(--color-content-default);
}
.bcn-omni-rail__item.is-active {
  background: var(--color-background-brand);
  color: var(--color-content-default-knockout);
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-omni-rail__item:disabled {
  color: var(--color-content-default-tertiary);
  cursor: default;
}
.bcn-omni-rail__label {
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.bcn-omni-rail__c {
  font-variant-numeric: tabular-nums;
  opacity: 0.8;
  flex: none;
  font-size: 11px;
}
.bcn-omni-group__head {
  align-items: center;
  gap: var(--spacing-200);
  padding: var(--spacing-200) var(--spacing-400) var(--spacing-100);
  display: flex;
}
.bcn-omni-group__label {
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-omni-group__count {
  font-size: var(--font-size-100);
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: 0 0;
  padding: 0 6px;
  line-height: 1.5;
}
.bcn-omni-row {
  width: 100%;
  padding: var(--spacing-250) var(--spacing-400);
  color: var(--color-content-default);
  text-align: left;
  cursor: pointer;
  background: 0 0;
  border: 0;
  align-items: center;
  font-family: inherit;
  display: flex;
}
.bcn-omni-row.is-active {
  background: var(--color-background-elevation-sunken);
}
.bcn-omni-row__text {
  flex-direction: column;
  flex: 1;
  gap: 3px;
  min-width: 0;
  display: flex;
}
.bcn-omni-row__titlerow {
  align-items: center;
  gap: var(--spacing-150);
  min-width: 0;
  display: flex;
}
.bcn-omni-row__code {
  border-radius: var(--radius-100);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  flex: none;
  padding: 1px 6px;
  line-height: 1.4;
}
.bcn-omni-row__title {
  min-width: 0;
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
  white-space: nowrap;
  text-overflow: ellipsis;
  flex: 0 auto;
  overflow: hidden;
}
.bcn-omni-row__snippet {
  font-family: var(--font-decorative);
  font-size: var(--font-size-150);
  color: var(--color-content-default);
  white-space: nowrap;
  text-overflow: ellipsis;
  margin-top: 2px;
  overflow: hidden;
}
.bcn-omni-row mark,
.bcn-omni-empty mark {
  color: var(--color-content-default);
  background: #fde047;
  border-radius: 2px;
  padding: 0 1px;
}

.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.typography-label-md-strong {
  font-family: var(--typography-label-md-strong-font-family);
  font-size: var(--typography-label-md-strong-font-size);
  font-weight: var(--typography-label-md-strong-font-weight);
  line-height: var(--typography-label-md-strong-line-height);
  letter-spacing: var(--typography-label-md-strong-letter-spacing);
}
.bcn-sr {
  gap: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.bcn-sr__search {
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-300) var(--spacing-400);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  display: flex;
}
.bcn-sr__search:focus-within {
  border-color: var(--color-background-brand);
  box-shadow: 0 0 0 3px var(--color-background-brand-subtle);
}
.bcn-sr__search-icon {
  color: var(--color-content-default-tertiary);
  flex-shrink: 0;
  display: inline-flex;
}
.bcn-sr__search-icon svg {
  width: 20px;
  height: 20px;
}
.bcn-sr__input {
  min-width: 0;
  font-family: inherit;
  font-size: var(--font-size-300);
  color: var(--color-content-default);
  background: 0 0;
  border: none;
  outline: none;
  flex: 1;
}
.bcn-sr__input::placeholder {
  color: var(--color-content-default-tertiary);
}
.bcn-sr__count {
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  margin: 0;
}
.bcn-sr__split {
  align-items: flex-start;
  gap: var(--spacing-500);
  display: flex;
}
.bcn-sr__rail {
  width: 220px;
  top: var(--spacing-400);
  flex-direction: column;
  flex: none;
  gap: 1px;
  display: flex;
  position: sticky;
}
.bcn-sr__main {
  gap: var(--spacing-400);
  border-left: 1px solid var(--color-border-default);
  min-width: 0;
  padding-left: var(--spacing-500);
  flex-direction: column;
  flex: auto;
  display: flex;
}
.bcn-sr__scope {
  align-items: center;
  gap: var(--spacing-200);
  width: 100%;
  padding: var(--spacing-200) var(--spacing-250);
  border-radius: var(--radius-200);
  color: var(--color-content-default-secondary);
  font-family: inherit;
  font-size: var(--font-size-150);
  text-align: left;
  cursor: pointer;
  background: 0 0;
  border: 0;
  transition:
    background 0.12s,
    color 0.12s;
  display: flex;
}
.bcn-sr__scope:hover {
  background: var(--color-background-elevation-sunken);
  color: var(--color-content-default);
}
.bcn-sr__scope--active {
  background: var(--color-background-brand);
  color: var(--color-content-default-knockout);
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-sr__scope-label {
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.bcn-sr__scope-count {
  font-variant-numeric: tabular-nums;
  opacity: 0.8;
  flex: none;
  font-size: 11px;
}
.bcn-sr--idle .bcn-sr__scope {
  color: var(--color-content-default-tertiary);
  cursor: default;
}
.bcn-sr--idle .bcn-sr__scope:hover {
  color: var(--color-content-default-tertiary);
  background: 0 0;
}
.bcn-sr--idle .bcn-sr__scope-count {
  display: none;
}
.bcn-sr__landing {
  padding: var(--spacing-700) 0;
}
.bcn-sr__landing[hidden],
.bcn-sr__results[hidden] {
  display: none;
}
.bcn-sr__results {
  gap: var(--spacing-500);
  flex-direction: column;
  display: flex;
}
.bcn-sr__group {
  gap: var(--spacing-150);
  flex-direction: column;
  display: flex;
}
.bcn-sr__group[hidden] {
  display: none;
}
.bcn-sr__group-head {
  align-items: center;
  gap: var(--spacing-200);
  padding: 0 var(--spacing-200) var(--spacing-150);
  border-bottom: 1px solid var(--color-border-default-subtle);
  display: flex;
}
.bcn-sr__group-label {
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-sr__group-count {
  font-size: var(--font-size-100);
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: 0 0;
  padding: 0 6px;
  line-height: 1.5;
}
.bcn-sr__rows {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.bcn-sr__row {
  gap: var(--spacing-150);
  padding: var(--spacing-200) var(--spacing-300);
  border-radius: var(--radius-200);
  color: var(--color-content-default);
  background: 0 0;
  flex-direction: column;
  text-decoration: none;
  transition: background 0.12s;
  display: flex;
}
.bcn-sr__row:hover {
  background: var(--color-background-elevation-sunken);
}
.bcn-sr__row[hidden] {
  display: none;
}
.bcn-sr__row-head {
  align-items: center;
  min-width: 0;
  display: flex;
}
.bcn-sr__row-titlerow {
  align-items: center;
  gap: var(--spacing-200);
  flex: 1;
  min-width: 0;
  display: flex;
}
.bcn-sr__row-code {
  border-radius: var(--radius-100);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  flex: none;
  padding: 1px 6px;
  line-height: 1.4;
}
.bcn-sr__row-title {
  min-width: 0;
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  white-space: nowrap;
  text-overflow: ellipsis;
  flex: 0 auto;
  overflow: hidden;
}
.bcn-sr__row-snippet {
  margin-top: var(--spacing-150);
  padding: var(--spacing-300) var(--spacing-350, 1.25rem);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  font-family: var(--font-decorative);
  font-size: var(--font-size-150);
  color: var(--color-content-default);
  text-align: left;
  line-height: 1.7;
}
.bcn-sr__row-snippet p {
  margin: 0;
}
.bcn-sr__row-snippet p + p {
  margin-top: 0.85em;
}
.bcn-sr__row-snippet .bcn-sr__row-more {
  border-top: 1px solid var(--color-border-default);
  font-family: var(--typography-font-family-sans, system-ui, sans-serif);
  font-size: var(--font-size-100);
  color: var(--color-content-default-tertiary);
  margin-top: 1em;
  padding-top: 0.7em;
  font-style: normal;
}
.bcn-sr__row-snippet[hidden] {
  display: none;
}
.bcn-sr__row-title mark,
.bcn-sr__row-snippet mark {
  color: var(--color-content-default);
  background: #fde047;
  border-radius: 2px;
  padding: 0 1px;
}
.bcn-sr__empty[hidden] {
  display: none;
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.typography-label-md-strong {
  font-family: var(--typography-label-md-strong-font-family);
  font-size: var(--typography-label-md-strong-font-size);
  font-weight: var(--typography-label-md-strong-font-weight);
  line-height: var(--typography-label-md-strong-line-height);
  letter-spacing: var(--typography-label-md-strong-letter-spacing);
}
.esa-empty-state {
  --_empty-icon-size: var(--empty-state-icon-size-md, 48px);
  --_empty-gap: var(--spacing-200, 0.5rem);
  text-align: center;
  padding: var(--spacing-600, 2rem) var(--spacing-400, 1rem);
  justify-content: center;
  align-items: center;
  gap: var(--_empty-gap);
  flex-direction: column;
  display: flex;
}
.esa-empty-state__icon {
  color: var(--color-content-default-secondary, #646464);
  margin-bottom: var(--spacing-100, 0.25rem);
  display: inline-flex;
}
.esa-empty-state__icon svg {
  width: var(--_empty-icon-size);
  height: var(--_empty-icon-size);
}
.esa-empty-state__title {
  color: var(--color-content-default, #202020);
  margin: 0;
}
.esa-empty-state__description {
  color: var(--color-content-default-secondary, #646464);
  max-width: 360px;
  margin: 0;
}
.esa-empty-state__actions {
  margin-top: var(--spacing-200, 0.5rem);
}
.esa-empty-state__actions:empty {
  display: none;
}

.bcn-sr__row {
  gap: var(--spacing-150);
  padding: var(--spacing-200) var(--spacing-300);
  border-radius: var(--radius-200);
  color: var(--color-content-default);
  background: 0 0;
  flex-direction: column;
  text-decoration: none;
  transition: background 0.12s;
  display: flex;
}
.bcn-sr__row:hover {
  background: var(--color-background-elevation-sunken);
}
.bcn-sr__row[hidden] {
  display: none;
}
.bcn-sr__row-head {
  align-items: center;
  min-width: 0;
  display: flex;
}
.bcn-sr__row-titlerow {
  align-items: center;
  gap: var(--spacing-200);
  flex: 1;
  min-width: 0;
  display: flex;
}
.bcn-sr__row-title {
  min-width: 0;
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  white-space: nowrap;
  text-overflow: ellipsis;
  flex: 0 auto;
  overflow: hidden;
}
.bcn-sr__row-snippet {
  margin-top: var(--spacing-150);
  padding: var(--spacing-300) var(--spacing-350, 1.25rem);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  font-family: var(--font-decorative);
  font-size: var(--font-size-150);
  color: var(--color-content-default);
  text-align: left;
  line-height: 1.7;
}
.bcn-sr__row-snippet p {
  margin: 0;
}
.bcn-sr__row-snippet p + p {
  margin-top: 0.85em;
}
.bcn-sr__row-snippet .bcn-sr__row-more {
  border-top: 1px solid var(--color-border-default);
  font-family: var(--typography-font-family-sans, system-ui, sans-serif);
  font-size: var(--font-size-100);
  color: var(--color-content-default-tertiary);
  margin-top: 1em;
  padding-top: 0.7em;
  font-style: normal;
}
.bcn-sr__row-snippet[hidden] {
  display: none;
}
.bcn-sr__row-title mark,
.bcn-sr__row-snippet mark {
  color: var(--color-content-default);
  background: #fde047;
  border-radius: 2px;
  padding: 0 1px;
}
